```yaml
name: Close unready PRs

on:
  pull_request:
    types: [opened, edited, reopened]

permissions:
  pull-requests: write
  issues: write

jobs:
  close-unready-pr:
    runs-on: ubuntu-latest
    steps:
      - name: Close PR if it references an unready issue
        uses: actions/github-script@v6
        with:
          script: |
            const core = require('@actions/core');
            const github = require('@actions/github');

            // Helper to log and exit
            const skip = (msg) => {
              core.info(msg);
              return;
            };

            // Get PR data
            const pr = github.context.payload.pull_request;
            if (!pr) {
              skip('No pull request data found.');
              return;
            }

            // Skip bot PRs
            if (pr.user.type === 'Bot') {
              skip(`Skipping bot PR from ${pr.user.login}.`);
              return;
            }

            // Skip maintainer PRs
            const org = 'mlflow';
            const actor = github.context.actor;
            try {
              await github.octokit.orgs.getMembershipForUser({
                org,
                username: actor
              });
              skip(`Skipping PR from maintainer ${actor}.`);
              return;
            } catch (e) {
              if (e.status !== 404) throw e; // rethrow unexpected errors
            }

            // Parse issue references from PR body
            const body = pr.body || '';
            const issueRefs = [];
            const issueRegex = /#(\\d+)|https?:\\/\\/github\\.com\\/[^\\/]+\\/[^\\/]+\\/issues\\/(\\d+)/g;
            let match;
            while ((match = issueRegex.exec(body)) !== null) {
              const issueNumber = match[1] || match[2];
              if (issueNumber) issueRefs.push(issueNumber);
            }

            if (issueRefs.length !== 1) {
              skip(`Skipping: ${issueRefs.length === 0 ? 'no' : 'multiple'} issue references found.`);
              return;
            }

            const issueNumber = issueRefs[0];
            const owner = github.context.repo.owner;
            const repo = github.context.repo.repo;

            // Fetch issue details
            let issue;
            try {
              const { data } = await github.octokit.issues.get({
                owner,
                repo,
                issue_number: issueNumber
              });
              issue = data;
            } catch (e) {
              skip(`Could not fetch issue #${issueNumber}: ${e.message}`);
              return;
            }

            // Skip issues created before the ready-label policy cutoff
            const cutoff = new Date('2026-03-10T00:00:00Z');
            const createdAt = new Date(issue.created_at);
            if (createdAt < cutoff) {
              skip(`Skipping: issue #${issueNumber} created before cutoff (${cutoff.toISOString()}).`);
              return;
            }

            // Skip if issue already has the 'ready' label
            const hasReady = issue.labels.some(l => l.name === 'ready');
            if (hasReady) {
              skip(`Issue #${issueNumber} already has the 'ready' label. No action taken.`);
              return;
            }

            // Close the PR
            await github.octokit.pulls.update({
              owner,
              repo,
              pull_number: pr.number,
              state: 'closed'
            });

            // Add a friendly comment
            const commentBody = `
:warning: This PR references issue #${issueNumber} which has not yet been triaged (missing the \`ready\` label).  
The PR has been closed until the issue is ready.  
Please reopen the PR once the issue is marked as \`ready\`.`;
            await github.octokit.issues.createComment({
              owner,
              repo,
              issue_number: pr.number,
              body: commentBody
            });

            core.info(`Closed PR #${pr.number} due to unready issue #${issueNumber}.`);
```

